create table export_preset (version integer, created timestamp(6) with time zone not null, id bigint generated by default as identity, modified timestamp(6) with time zone, name varchar(2048) not null unique, created_by varchar(255), modified_by varchar(255), config json not null, primary key (id));
create table export_preset_aud (rev integer not null, revtype smallint, id bigint not null, name varchar(2048), config json, primary key (rev, id));
